SELECT n.nspname AS schema_name, p.proname AS routine_name, oidvectortypes(p.proargtypes) AS arguments, format_type(p.prorettype, NULL) AS return_type, p.provolatile AS volatility, p.prosecdef AS security_definer, l.lanname AS language, u.usename AS owner, p.prokind AS kind FROM pg_proc_info p JOIN pg_namespace n ON p.pronamespace = n.oid JOIN pg_language l ON p.prolang = l.oid LEFT JOIN pg_user u ON p.proowner = u.usesysid WHERE p.prokind = 'p' AND n.nspname !~ '^pg_' AND n.nspname <> 'information_schema' AND n.nspname = :schema ORDER BY schema_name, routine_name, arguments;
